  campos = $uonisign$[{"chave":"Contratante","rotulo":"Razão social","tipo":"texto","grupo":"Dados da Contratante","min":3,"max":150},{"chave":"CNPJ_do_Contratante","rotulo":"CNPJ","tipo":"cnpj","grupo":"Dados da Contratante"},{"chave":"CEP","rotulo":"CEP","tipo":"cep","grupo":"Dados da Contratante"},{"chave":"Logradouro","rotulo":"Rua ou avenida","tipo":"texto","grupo":"Dados da Contratante","max":150},{"chave":"Numero","rotulo":"Número","tipo":"texto","grupo":"Dados da Contratante","max":10,"ajuda":"Aceita S/N"},{"chave":"Complemento","rotulo":"Complemento","tipo":"texto","grupo":"Dados da Contratante","obrigatorio":false,"max":60},{"chave":"Bairro","rotulo":"Bairro","tipo":"texto","grupo":"Dados da Contratante","max":80},{"chave":"Cidade","rotulo":"Cidade","tipo":"texto","grupo":"Dados da Contratante","max":80},{"chave":"Estado","rotulo":"UF","tipo":"uf","grupo":"Dados da Contratante"},{"chave":"Representante_Legal","rotulo":"Representante legal","tipo":"texto","grupo":"Dados da Contratante","min":3,"max":120,"ajuda":"Também será o signatário da Contratante"},{"chave":"Identidade","rotulo":"RG do representante","tipo":"texto","grupo":"Dados da Contratante","max":20},{"chave":"CPF","rotulo":"CPF do representante","tipo":"cpf","grupo":"Dados da Contratante"},{"chave":"Valor_Passeio_Moto","rotulo":"Passeio ou moto, por veículo ativo (R$)","tipo":"moeda","grupo":"Valores","clausula":"2.1","padrao":"3,90"},{"chave":"Valor_Caminhao","rotulo":"Caminhão, por veículo ativo (R$)","tipo":"moeda","grupo":"Valores","clausula":"2.1","padrao":"10,80"},{"chave":"Valor_Minimo_Mensal","rotulo":"Valor mínimo mensal (R$)","tipo":"moeda","grupo":"Valores","clausula":"2.1","padrao":"600,00","soma_valor":true},{"chave":"Email","rotulo":"E-mail da Contratante","tipo":"email","grupo":"E-mails e responsável financeiro","clausula":"15.1","ajuda":"Recebe as notificações e o convite de assinatura"},{"chave":"Data_Inicio","rotulo":"Data de início","tipo":"data","grupo":"Vigência"},{"chave":"P